actions.script:
def sb = new StringBuilder()
chs.each { ch -> sb.append(ch.text ?: '').append('\n') }
content = sb.toString().trim()

set.from:
templates.collect { t -> [agentName: t.agentName, teamName: t.teamName,
                catalogCategory: t.catalogCategory, description: t.description, agentRole: t.agentRole ?: 'specialist',
                scheduleEnabled: t.scheduleEnabled == 'Y', writePolicy: t.writePolicy ?: 'approve'] }

actions.script:
import org.moqui.adk.AdkManager
import groovy.json.JsonSlurper

outcome = 'error'
message = 'Could not check feasibility right now.'
draft = null

if (!AdkManager.isInitialized()) AdkManager.lazyInit(ec.factory)
if (!AdkManager.isInitialized()) {
    message = 'AI is not configured for this company yet.'
} else {
    try {
        Map sessionCtx = [
            userId          : (ec.user.userId ?: 'suggest') as String,
            username        : (ec.user.username ?: 'suggest') as String,
            userFullName    : (ec.user.username ?: 'Suggest') as String,
            organizationName: '',
            companyPseudoId : '',
            tenantId        : ownerPartyId as String,
            timeZone        : 'UTC',
            locale          : 'en_US',
            screenCatalog   : (screenCatalogJson ?: '[]') as String,
        ]
        List events = AdkManager.runOneOff(
            scoutCfg.adkAgentConfigId as String, sessionCtx.userId as String,
            description, sessionCtx)

        StringBuilder sb = new StringBuilder()
        events.each { e ->
            if (e.author != sessionCtx.userId && e.partial != true) {
                e.content?.parts?.each { p -> if (p.text) sb.append(p.text) }
            }
        }
        String resultText = sb.toString().trim()

        def m = (resultText =~ /(?s)```suggestion\s*(\{.*?\})\s*```/)
        if (m.find()) {
            def parsed = new JsonSlurper().parseText(m.group(1)) as Map
            outcome = (parsed.outcome ?: 'error') as String
            message = (parsed.message ?: '') as String
            draft = parsed.draft as Map
        } else {
            ec.logger.warn("suggest#AgentFunction: no JSON block in Scout reply: ${resultText}")
            message = 'Could not parse a feasibility check right now. Try rephrasing the request.'
        }
    } catch (Throwable t) {
        ec.logger.error("suggest#AgentFunction failed: ${t.message}", t)
        message = "Feasibility check failed: ${t.message}"
    }
}

def v = { String name, def given -> given != null ? given : cfg?.get(name) }
String instr = v('instruction', instruction) ?: ''
String prompt = v('schedulePrompt', schedulePrompt) ?: ''
String provider = v('llmProvider', llmProvider) ?: 'gemini'
String mode = v('toolMode', toolMode) ?: 'readOnly'
String allow = v('serviceAllowlist', serviceAllowlist) ?: ''
String policy = v('writePolicy', writePolicy) ?: 'approve'
boolean search = webSearch != null ? webSearch : cfg?.webSearch == 'Y'
boolean scheduled = scheduleEnabled != null ? scheduleEnabled : cfg?.scheduleEnabled == 'Y'
String cron = v('scheduleExpression', scheduleExpression) ?: ''
Integer maxCalls = v('maxLlmCalls', maxLlmCalls) as Integer
issues = []

// ADK reads {name} as a session-state variable (same rule as its InstructionUtils):
// an identifier, optional '?' suffix, optional app:/user:/temp: prefix. Only these
// keys are seeded for every run (scheduler, chat, suggest, test).
def knownKeys = ['userId', 'username', 'userFullName', 'organizationName', 'companyPseudoId',
                 'tenantId', 'timeZone', 'locale', 'memory', 'screenCatalog'] as Set
[instruction: instr, schedulePrompt: prompt].each { field, text ->
    (text =~ /\{+([^{}]*)\}+/).each { m ->
        String key = (m[1] as String).trim()
        if (key.endsWith('?') || key.startsWith('artifact.')) return
        String bare = key.replaceFirst(/^(app|user|temp):/, '')
        if (!(bare ==~ /[A-Za-z_][A-Za-z0-9_]*/)) return
        if (key != bare)
            issues << [level: 'warning', field: field, message: "{${key}} must be set in session state before the run, or the run fails."]
        else if (!knownKeys.contains(key))
            issues << [level: 'error', field: field, message: "{${key}} is read as a variable that does not exist, so the run fails. Write [${key}] instead."]
    }
}
if (!instr.trim() && !prompt.trim())
    issues << [level: 'error', field: 'instruction', message: 'Set an instruction or a scheduled-run prompt.']
if (mode == 'scoped') {
    def globs = allow.split(/[,\s]+/).findAll { it }
    if (!globs) {
        issues << [level: 'error', field: 'serviceAllowlist', message: 'Tool access is scoped but no services are allowed.']
    } else {
        Set names = null
        try { names = org.moqui.mcp.adapter.McpToolAdapter.getCachedGroWerpServiceNames(ec) } catch (Throwable ignore) { }
        if (names) globs.each { String g ->
            def rx = '^' + g.split(/\*/, -1).collect { it ? java.util.regex.Pattern.quote(it) : '' }.join('.*') + '$'
            if (!names.any { it ==~ rx })
                issues << [level: 'warning', field: 'serviceAllowlist', message: "Allowed service '${g}' matches no service."]
        }
    }
}
if (mode == 'full' && policy == 'allow')
    issues << [level: 'warning', field: 'writePolicy', message: 'Full tool access with auto-run writes: the agent can change any data without approval.']
if (search && provider != 'gemini')
    issues << [level: 'warning', field: 'webSearch', message: "Web search only works with Gemini; it is ignored for ${provider}."]
if (maxCalls != null && maxCalls < 1)
    issues << [level: 'error', field: 'maxLlmCalls', message: 'Max AI calls per run must be at least 1.']
if (scheduled && !cron.trim())
    issues << [level: 'error', field: 'scheduleExpression', message: 'Scheduled runs are on but there is no cron expression.']
